import {createAtom,TanStackStoreAtom,type Atom} from "@tanstack/lit-store";
import type {ReactiveElement} from "lit";

type Host=ReactiveElement;
class NamedAtom<T> extends TanStackStoreAtom<T>{
 private last:T;
 constructor(private host:Host,private name:PropertyKey,private store:Atom<T>){
  super(host,()=>store);
  this.last=store.get();
  let subscription:{unsubscribe:()=>void}|undefined;
  const sync=(value:T)=>{const previous=this.last;this.last=value;if(!Object.is(previous,value))host.requestUpdate(name,previous);};
  host.addController({
   hostConnected:()=>{sync(store.get());subscription=store.subscribe(sync);},
   hostDisconnected:()=>{subscription?.unsubscribe();subscription=undefined;}
  });
 }
 override set(value:T|((prev:T)=>T)){
  const previous=this.store.get();
  if(typeof value==="function") super.set(value as (prev:T)=>T);
  else super.set(value);
  this.last=this.store.get();
  this.host.requestUpdate(this.name,previous);
 }
}
const atoms=new WeakMap<Host,Map<PropertyKey,NamedAtom<unknown>>>();
export function atomState<T>(shared?:Atom<T>,options?:{compare?:(a:T,b:T)=>boolean}){
 return (proto:object,name:PropertyKey)=>{
  (proto.constructor as typeof ReactiveElement).addInitializer(host=>{
   atomFor(host,name,shared,options);
   if(shared)host.requestUpdate(name,undefined);
  });
  Object.defineProperty(proto,name,{
   configurable:true,enumerable:true,
   get(this:Host){return atomFor<T>(this,name,shared,options).value;},
   set(this:Host,value:T){atomFor<T>(this,name,shared,options).set(()=>value);}
  });
 };
}
function atomFor<T>(host:Host,name:PropertyKey,shared?:Atom<T>,options?:{compare?:(a:T,b:T)=>boolean}):NamedAtom<T>{
 let map=atoms.get(host);if(!map)atoms.set(host,map=new Map());
 let bound=map.get(name) as NamedAtom<T>|undefined;
 if(!bound){bound=new NamedAtom(host,name,shared??createAtom(undefined as T,options as never));map.set(name,bound as NamedAtom<unknown>);}
 return bound;
}

